files.src/components/Chip.jsx:
import React, { useState } from 'react';

export function Chip({
  Size = 'M',
  Icon = false,
  Label = 'Filter',
  className
}) {
  const [pressed, setPressed] = useState(false);

  const sizeClass = Size === 'L' ? 'chip--l' : '';
  const iconClass = Icon ? 'chip--icon' : '';

  return (
    <button
      type="button"
      role="button"
      aria-pressed={pressed}
      onClick={() => setPressed(!pressed)}
      className={`chip ${sizeClass} ${iconClass} ${className || ''}`}
      title={Label}
    >
      {Icon && (
        <span className="chip__icon" aria-hidden="true">
          ●
        </span>
      )}
      <span className="chip__label">{Label}</span>
    </button>
  );
}

export default Chip;

