const assetPathPrefix = "https://www.figma.com/api/mcp/asset/7ddc2f51-708b-4445-8a5c-b1ad338d4e2a";
const imgIcon = `${assetPathPrefix}/a027b.svg`;

export default function Chip({
  Size = "M",
  Icon = false,
  Label = "Filter",
  pressed = false,
  onChange,
  className,
}) {
  const sizeClass = Size === "L" ? "chip--l" : "";
  const baseClass = `chip ${sizeClass}`.trim();
  const finalClass = className ? `${baseClass} ${className}` : baseClass;

  const showIcon = Icon && Size === "L";
  const ariaLabel = showIcon ? Label : undefined;

  return (
    <button
      type="button"
      role="togglebutton"
      aria-pressed={pressed}
      aria-label={ariaLabel}
      className={finalClass}
      onClick={() => onChange?.(!pressed)}
    >
      {showIcon && (
        <img
          alt=""
          className="chip__icon"
          src={imgIcon}
        />
      )}
      <span className="chip__label">{Label}</span>
    </button>
  );
}

