import '../styles/chip.css';

export function Chip({
  Size = 'M',
  Icon = false,
  Label = 'Filter',
  pressed = false,
  onPress,
  className,
}) {
  const chipClass = `chip ${Size === 'L' ? 'chip--l' : ''} ${className || ''}`.trim();

  const handleClick = () => {
    if (onPress) onPress(!pressed);
  };

  const showIcon = Size === 'L' && Icon;

  return (
    <button
      type="button"
      className={chipClass}
      role="switch"
      aria-pressed={pressed}
      aria-label={showIcon ? Label : undefined}
      onClick={handleClick}
    >
      {showIcon && (
        <svg
          className="chip__icon"
          viewBox="0 0 12 12"
          fill="currentColor"
          aria-hidden="true"
        >
          <circle cx="6" cy="6" r="6" />
        </svg>
      )}
      {!showIcon && (
        <span className="chip__label">{Label}</span>
      )}
      {showIcon && (
        <span className="chip__label">{Label}</span>
      )}
    </button>
  );
}

