import React from 'react';

export default function Field({
  State = 'Default',
  label,
  error,
  value = '',
  onChange,
  placeholder,
  ...props
}) {
  const isError = State === 'Error';
  const errorId = isError && error ? 'field-error' : undefined;

  return (
    <div>
      {label && (
        <label htmlFor="field-input" className="field-label">
          {label}
        </label>
      )}
      <input
        id="field-input"
        type="text"
        className={`field ${isError ? 'field--error' : ''}`}
        value={value}
        onChange={onChange}
        placeholder={placeholder}
        aria-invalid={isError}
        aria-describedby={errorId}
        {...props}
      />
      {isError && error && (
        <div id="field-error" className="field-error-message">
          {error}
        </div>
      )}
    </div>
  );
}

