files.src/components/Tag.jsx:
export default function Tag({ className, Label = "New", Tone = "Neutral" }) {
  const isPositive = Tone === "Positive";
  const tagClass = `tag${isPositive ? " tag--positive" : ""}${className ? ` ${className}` : ""}`;

  return (
    <div className={tagClass}>
      {Label}
    </div>
  );
}

